package com.vinnyvangogh.groupironman;

import com.google.common.base.Charsets;
import com.google.gson.*;
import com.google.gson.annotations.SerializedName;
import java.io.*;
import java.util.*;
import java.util.List;

/**
 * The quest items the Shopping tab's presets are built from: a subset of
 * Quest Path's bundled {@code quests.json}, generated by
 * {@code scripts/gen-quest-items.py} and checked by {@code QuestDataTest}.
 *
 * <p>Copied, never linked: GIM Utilities does not depend on Quest Path at
 * runtime (no reflection, no plugin message to it). The resource names the
 * Quest Path commit it came from in {@link #source()}.
 *
 * <p>Only the quests some preset reaches (the presets' quests and every
 * prerequisite, followed to the end) are carried, with the shops and monster
 * locations their items name, plus every quest's name by id so a shop gated
 * behind any quest can still be judged.
 */
final class QuestData
{
	static final String RESOURCE = "quest-items.json";

	@SerializedName("source")
	private Map<String, String> source;

	@SerializedName("quests")
	private List<Quest> quests;

	@SerializedName("quest_names")
	private Map<String, String> questNames;

	@SerializedName("shops")
	private List<Shop> shops;

	@SerializedName("drop_locations")
	private List<DropLocation> dropLocations;

	private transient Map<String, Quest> byName;
	private transient Map<Long, Quest> byId;
	private transient Map<String, Shop> shopsByName;
	private transient Map<Integer, Item> itemsById;

	/** One quest: what it needs, what it grants, what must come first. */
	static final class Quest
	{
		@SerializedName("id")
		private long id;

		@SerializedName("name")
		private String name;

		@SerializedName("members")
		private boolean members;

		@SerializedName("prerequisites")
		private List<Long> prerequisites;

		@SerializedName("prerequisites_started_only")
		private List<Long> prerequisitesStartedOnly;

		@SerializedName("requirements")
		private List<Level> requirements;

		@SerializedName("rewards")
		private List<Reward> rewards;

		@SerializedName("items")
		private List<Item> items;

		long id()
		{
			return id;
		}

		String name()
		{
			return name == null ? "" : name;
		}

		boolean members()
		{
			return members;
		}

		List<Long> prerequisites()
		{
			return prerequisites == null ? Collections.emptyList() : prerequisites;
		}

		/** A prerequisite satisfied by having started it, not finished it. */
		boolean startedOnly(long prerequisite)
		{
			return prerequisitesStartedOnly != null && prerequisitesStartedOnly.contains(prerequisite);
		}

		List<Level> requirements()
		{
			return requirements == null ? Collections.emptyList() : requirements;
		}

		List<Reward> rewards()
		{
			return rewards == null ? Collections.emptyList() : rewards;
		}

		List<Item> items()
		{
			return items == null ? Collections.emptyList() : items;
		}
	}

	/** A skill level a quest or a shop demands; {@code skill} lowercase as the bundle spells it. */
	static final class Level
	{
		@SerializedName("skill")
		private String skill;

		@SerializedName("level")
		private int level;

		@SerializedName("boostable")
		private boolean boostable;

		String skill()
		{
			return skill == null ? "" : skill;
		}

		int level()
		{
			return level;
		}

		boolean boostable()
		{
			return boostable;
		}
	}

	/** Experience a quest grants. */
	static final class Reward
	{
		@SerializedName("skill")
		private String skill;

		@SerializedName("xp")
		private double xp;

		String skill()
		{
			return skill == null ? "" : skill;
		}

		double xp()
		{
			return xp;
		}
	}

	/** One line of a quest's item list, as Quest Path's wiki import resolved it. */
	static final class Item
	{
		@SerializedName("name")
		private String name;

		@SerializedName("item_id")
		private int itemId;

		@SerializedName("quantity")
		private int quantity;

		@SerializedName("optional")
		private boolean optional;

		@SerializedName("obtainable")
		private boolean obtainable;

		@SerializedName("unresolved")
		private boolean unresolved;

		@SerializedName("grouped")
		private boolean grouped;

		@SerializedName("sources")
		private List<String> sources;

		@SerializedName("shop_names")
		private List<String> shopNames;

		@SerializedName("drop_source_names")
		private List<String> dropSourceNames;

		String name()
		{
			return name == null ? "" : name;
		}

		/** 0 when Quest Path holds no id: never item 0. */
		int itemId()
		{
			return itemId;
		}

		/** The count the wiki stated, 0 when it stated none. */
		int quantity()
		{
			return quantity;
		}

		boolean optional()
		{
			return optional;
		}

		/** The wiki says it can be picked up during the quest. */
		boolean obtainable()
		{
			return obtainable;
		}

		/** A wiki line Quest Path could not match to one item. */
		boolean unresolved()
		{
			return unresolved;
		}

		/** A category ("any pickaxe") rather than one item. */
		boolean grouped()
		{
			return grouped;
		}

		/** "Shop: Tynan's Fishing Supplies (2 Coins)", "Drop: Goblin (Always)": display lines, best first. */
		List<String> sources()
		{
			return sources == null ? Collections.emptyList() : sources;
		}

		/** Shops in {@link QuestData#shop} that sell it, best first. */
		List<String> shopNames()
		{
			return shopNames == null ? Collections.emptyList() : shopNames;
		}

		List<String> dropSourceNames()
		{
			return dropSourceNames == null ? Collections.emptyList() : dropSourceNames;
		}
	}

	/** A shop with a walkable tile, and what stands in the way of being served there. */
	static final class Shop
	{
		@SerializedName("name")
		private String name;

		/** The shop's tile; plane 0 for the ground floor, which is nearly every shop. */
		@SerializedName("x")
		int x;

		@SerializedName("y")
		int y;

		@SerializedName("plane")
		int plane;

		@SerializedName("town")
		private String town;

		@SerializedName("reachability")
		private Reachability reachability;

		String name()
		{
			return name == null ? "" : name;
		}

		String town()
		{
			return town == null ? "" : town;
		}

		/** Null for most shops: nothing stands in the way. */
		Reachability reachability()
		{
			return reachability;
		}
	}

	/** Skill levels and quests a shop is behind. */
	static final class Reachability
	{
		@SerializedName("required_skills")
		private List<Level> requiredSkills;

		@SerializedName("required_quest_ids")
		private List<Long> requiredQuestIds;

		@SerializedName("required_quest_ids_started_only")
		private List<Long> startedOnlyQuestIds;

		@SerializedName("unknown")
		private boolean unknown;

		/** Quest Path knows the shop is behind something but not what: never treated as open. */
		boolean unknown()
		{
			return unknown;
		}

		List<Level> requiredSkills()
		{
			return requiredSkills == null ? Collections.emptyList() : requiredSkills;
		}

		List<Long> requiredQuestIds()
		{
			return requiredQuestIds == null ? Collections.emptyList() : requiredQuestIds;
		}

		boolean startedOnly(long questId)
		{
			return startedOnlyQuestIds != null && startedOnlyQuestIds.contains(questId);
		}
	}

	/** Where a monster that drops something can be found. */
	static final class DropLocation
	{
		@SerializedName("source_name")
		private String sourceName;

		@SerializedName("region")
		private String region;

		String sourceName()
		{
			return sourceName == null ? "" : sourceName;
		}

		/** "general", "wilderness", ...; empty when not known. */
		String region()
		{
			return region == null ? "" : region;
		}
	}

	/** Where this data came from: repo, commit, path and Quest Path graph version. */
	Map<String, String> source()
	{
		return source == null ? Collections.emptyMap() : Collections.unmodifiableMap(source);
	}

	List<Quest> quests()
	{
		return quests == null ? Collections.emptyList() : quests;
	}

	/** One quest by its exact name, or null. */
	Quest quest(String name)
	{
		if (byName == null)
		{
			Map<String, Quest> index = new LinkedHashMap<>();
			for (Quest q : quests())
			{
				index.put(q.name(), q);
			}
			byName = index;
		}
		return byName.get(name);
	}

	/** One carried quest by id, or null. */
	Quest quest(long id)
	{
		if (byId == null)
		{
			Map<Long, Quest> index = new LinkedHashMap<>();
			for (Quest q : quests())
			{
				index.put(q.id(), q);
			}
			byId = index;
		}
		return byId.get(id);
	}

	/** Any quest's name by id, carried or not; null when the source had no such quest. */
	String questName(long id)
	{
		return questNames == null ? null : questNames.get(Long.toString(id));
	}

	/** Every quest name the source knows, for judging shop gates. */
	Map<String, String> questNames()
	{
		return questNames == null ? Collections.emptyMap() : Collections.unmodifiableMap(questNames);
	}

	/**
	 * The first shoppable line anywhere in the data for this item, or null. Every line naming one item carries the
	 * same sources (Quest Path looks them up once per item), so any one stands for all; a custom list's item finds
	 * its shops this way.
	 */
	Item item(int itemId)
	{
		if (itemsById == null)
		{
			Map<Integer, Item> index = new LinkedHashMap<>();
			for (Quest q : quests())
			{
				for (Item i : q.items())
				{
					if (ShopNeeds.shoppable(i))
					{
						index.putIfAbsent(i.itemId(), i);
					}
				}
			}
			itemsById = index;
		}
		return itemsById.get(itemId);
	}

	/** One shop by exact name, or null when the data does not carry it. */
	Shop shop(String name)
	{
		if (shopsByName == null)
		{
			Map<String, Shop> index = new LinkedHashMap<>();
			for (Shop s : shops == null ? Collections.<Shop>emptyList() : shops)
			{
				index.put(s.name(), s);
			}
			shopsByName = index;
		}
		return shopsByName.get(name);
	}

	List<Shop> shops()
	{
		return shops == null ? Collections.emptyList() : shops;
	}

	List<DropLocation> dropLocations()
	{
		return dropLocations == null ? Collections.emptyList() : dropLocations;
	}

	/** The bundled data. Never fails: a missing or broken resource is empty data, and the tab says so. */
	static QuestData load(Gson gson)
	{
		try (InputStream in = QuestData.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				return empty();
			}
			return parse(gson, new InputStreamReader(in, Charsets.UTF_8));
		}
		catch (IOException e)
		{
			return empty();
		}
	}

	static QuestData parse(Gson gson, Reader reader) throws IOException
	{
		try
		{
			QuestData data = gson.fromJson(reader, QuestData.class);
			if (data == null)
			{
				throw new IOException("empty quest data");
			}
			return data;
		}
		catch (JsonParseException e)
		{
			throw new IOException("quest data did not parse: " + e.getMessage(), e);
		}
	}

	static QuestData empty()
	{
		return new QuestData();
	}
}
